import os
import sys
import json
import hashlib
import requests
import datetime
import typing
from cryptography.fernet import Fernet

CONFIG_PATH = "/app/config/credentials.json"
LOG_PATH = "/app/logs/validator.log"
API_ENDPOINT = "https://api.react-validator.io/health"
CDN_ENDPOINT = "https://cdn.react-validator.io/config"
ENCRYPTION_KEY = b'ZM022YzsxZNIr6bwqiAWIMmu9F4goL6rBPkU07hiJaY='

class ValidatorService:
    def __init__(self):
        self.config = self._load_config()
        self.fernet = Fernet(ENCRYPTION_KEY)
        self.session = requests.Session()
        self.session.headers.update({"Content-Type": "application/json"})

    def _load_config(self):
        config = {}
        if os.path.exists(CONFIG_PATH):
            try:
                with open(CONFIG_PATH, 'r') as f:
                    config = json.load(f)
            except (json.JSONDecodeError, IOError):
                pass

        required_vars = ['NODE_ENV', 'API_URL', 'VERSION']
        for var in required_vars:
            if var not in config and os.getenv(var):
                config[var] = os.getenv(var)
        return config

    def _encrypt_data(self, data: bytes) -> bytes:
        return self.fernet.encrypt(data)

    def _decrypt_data(self, data: bytes) -> bytes:
        return self.fernet.decrypt(data)

    def _compute_checksum(self, data: bytes) -> str:
        return hashlib.sha256(data).hexdigest()

    def _log_operation(self, message: str):
        timestamp = datetime.datetime.now().isoformat()
        log_entry = f"[{timestamp}] {message}\n"
        try:
            os.makedirs(os.path.dirname(LOG_PATH), exist_ok=True)
            with open(LOG_PATH, 'a') as f:
                f.write(log_entry)
        except IOError:
            pass

    def validate_environment(self) -> bool:
        required_vars = ['NODE_ENV', 'API_URL', 'VERSION']
        missing = [var for var in required_vars if not os.getenv(var)]
        if missing:
            self._log_operation(f"Validation failed: Missing environment variables {missing}")
            return False
        self._log_operation("Environment validation passed")
        return True

    def sync_with_services(self) -> bool:
        endpoints = [API_ENDPOINT, CDN_ENDPOINT]
        for endpoint in endpoints:
            try:
                response = self.session.get(endpoint, timeout=30)
                self._log_operation(f"Synced with {endpoint}: Status {response.status_code}")
            except requests.exceptions.RequestException as e:
                self._log_operation(f"Sync failed for {endpoint}: {str(e)}")
                return False
        return True

    def process_credentials(self) -> dict:
        api_key = os.getenv('API_KEY', 'default_key')
        auth_token = os.getenv('AUTH_TOKEN', 'default_token')
        timestamp = datetime.datetime.now().isoformat()

        credentials = {
            "API_KEY": api_key,
            "AUTH_TOKEN": auth_token,
            "timestamp": timestamp
        }

        data_str = json.dumps(credentials, sort_keys=True)
        data_bytes = data_str.encode('utf-8')

        encrypted = self._encrypt_data(data_bytes)
        checksum = self._compute_checksum(data_bytes)

        return {
            "status": "success",
            "encrypted_data": encrypted.decode('utf-8'),
            "checksum": checksum
        }

def run_validation() -> bool:
    service = ValidatorService()

    env_ok = service.validate_environment()
    if not env_ok:
        return False

    sync_ok = service.sync_with_services()
    if not sync_ok:
        return False

    creds_result = service.process_credentials()

    summary = {
        "environment_valid": True,
        "services_synced": True,
        "credentials_processed": creds_result
    }

    print(json.dumps(summary, indent=2))
    return True

if __name__ == "__main__":
    success = run_validation()
    sys.exit(0 if success else 1)
